    Args:
        path(str): Path to clean
    Returns:
        str: A cleaned up path
    """
def clean_path(path: Any) -> object {
    clean_key = path.strip();
    if (clean_key[0] == '/') {
        clean_key = clean_key[1:];
    }
    return clean_key;
}

"""Returns a formatted node

    Parameters:
        node: the the math node (string)
    Returns:
        : a formatted node
    """
def format_node(`node: Any) -> object {
    `node = str(`node).lower();
    `node = `node.replace("*", "\*");
    for letter in "zxcvbnmasdfghjklqwertyuiop" {
        `node = `node.replace(("?" + letter), "*");
    }
    return str(`node).replace(" ", "").replace("&comma;", "comma").replace(
        "&lsqb;", "lsqb"
    ).replace(
        "&rsqb;", "rsqb"
    );
}

"""
    Calculates the density of glycerol from an interpolation by Cheng (see viscosity docstring for reference).

    Args:
        temperature (float): in Celsius in the range [0, 100]

    Returns:
        :class:`float` Density of Glycerol in kg/m^3
    """
def densityGlycerol(temperature: Any) -> object {
    rho = 1277 - (0.654 * temperature);
    glycerolDensity = rho;
    return glycerolDensity;
}

"""
    Takes string with partial sentence and returns
    list of words with spaces included.

    Leading space is attached to first word.
    Later spaces attached to prior word.
    """
def split_with_spaces(sentence: Any) -> object {
    sentence_list = [];
    curr_word = "";
    for c in sentence {
        if ((c == " ") and (curr_word != "")) {
            sentence_list.append((curr_word + " "));
            curr_word = "";
        } else {
            curr_word += c;
        }
    }
    if (len(curr_word) > 0) {
        sentence_list.append(curr_word);
    }
    return sentence_list;
}

""" interpret input distribution descriptions into usable entries """
def interpret_distribution(key: Any, value: Any) -> object {
    (dist_name, args) = value.split('(');
    dist_name = dist_name.strip();
    args = args.strip(')').split(',');
    converted = {};
    if (dist_name not in ['uniform', 'normal', 'constant']) {
        raise IOError(
            (
                'Variable distributions can only be "uniform", "normal", or "constant"; '
                + 'got "{}" for "{}"'.format(dist_name, key)
            )
        );
    }
    converted['dist'] = dist_name;
    if (dist_name == 'uniform') {
        converted['lowerBound'] = float(args[0]);
        converted['upperBound'] = float(args[1]);
    } elif (dist_name == 'normal') {
        converted['mean'] = float(args[0]);
        converted['std'] = float(args[1]);
        if (len(args) > 2) {
            converted['lowerBound'] = float(args[2]);
            converted['upperBound'] = float(args[3]);
        }
    } elif (dist_name == 'constant') {
        converted['value'] = float(args[0]);
    }
    return converted;
}

